def _extract_code(self, response: str) -> str:
    """Extract Python code from a VLM response."""
    # Look for code blocks — find the LAST ```python block (skip thinking blocks)
    import re
    blocks = list(re.finditer(r'```python\s*\n(.*?)```', response, re.DOTALL))
    if blocks:
        return blocks[-1].group(1).strip()
    # Fallback: find ```python without closing ```
    if "```python" in response:
        start = response.rindex("```python") + len("```python")
        try:
            end = response.index("```", start)
            return response[start:end].strip()
        except ValueError:
            return response[start:].strip()
    elif "```" in response:
        start = response.index("```") + 3
        try:
            end = response.index("```", start)
            return response[start:end].strip()
        except ValueError:
            return response[start:].strip()
    return response.strip()

